# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import absence_notice

STUDENT = Student("1", "Thistle", "Bram", "A")


def mark(day, status="absent", student_id="1"):
    return Mark(student_id, date(2026, 3, day), status)


class NoticeTests(unittest.TestCase):
    def test_names_student_and_count(self):
        text = absence_notice(STUDENT, [mark(9), mark(2), mark(5, "present")])
        self.assertIn("Bram Thistle missed 2 days", text)

    def test_dates_are_in_order(self):
        text = absence_notice(STUDENT, [mark(9), mark(2)])
        self.assertTrue(text.endswith("2026-03-02, 2026-03-09"))

    def test_single_day_is_singular(self):
        self.assertIn("missed 1 day ", absence_notice(STUDENT, [mark(4)]))

    def test_other_students_mark_is_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [mark(4), mark(5, student_id="2")])

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [mark(4, "late")])

    def test_empty_marks_is_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [])
